// Fixed explanations for basic terms, written by people, never generated by AI.
// The AI only picks WHICH topic a question is about; the words below are always the same.
// Where a topic has numbers in this APBDes (e.g. how much Dana Desa), code adds them.

import type { ParsedBudgetItem } from "@/features/apbdes/types";
import { formatRupiah } from "@/lib/format";

export const GLOSSARY_TOPICS = [
  "APBDES",
  "DANA_DESA",
  "ADD",
  "PADES",
  "SILPA",
  "BIDANG",
  "REALISASI",
  "BLT_DD",
  "DANA_PER_RT",
  "USUL_KEGIATAN",
] as const;

export type GlossaryTopic = (typeof GLOSSARY_TOPICS)[number];

interface GlossaryEntry {
  text: string;
  // Rows of this APBDes that belong to the topic (used as sources). Optional.
  related?: (items: ParsedBudgetItem[]) => ParsedBudgetItem[];
  // A sentence with real numbers from those rows. Optional.
  figure?: (rows: ParsedBudgetItem[]) => string | null;
}

const sumBudget = (rows: ParsedBudgetItem[]) => rows.reduce((total, item) => total + item.budget, 0);

const revenueFrom = (source: ParsedBudgetItem["fundSource"]) => (items: ParsedBudgetItem[]) =>
  items.filter((item) => item.entryType === "REVENUE" && item.fundSource === source);

const amountSentence = (label: string) => (rows: ParsedBudgetItem[]) =>
  rows.length === 0 ? null : `Di APBDes ini, ${label} dianggarkan ${formatRupiah(sumBudget(rows))}.`;

export const GLOSSARY: Record<GlossaryTopic, GlossaryEntry> = {
  APBDES: {
    text:
      "APBDes (Anggaran Pendapatan dan Belanja Desa) adalah rencana keuangan tahunan desa: " +
      "dari mana uang desa berasal (pendapatan) dan untuk apa dipakai (belanja). " +
      "APBDes dibahas dan disepakati kepala desa bersama BPD, lalu ditetapkan dengan Peraturan Desa.",
  },
  DANA_DESA: {
    text:
      "Dana Desa adalah dana dari APBN (pemerintah pusat) yang disalurkan ke desa melalui kabupaten, " +
      "terutama untuk pembangunan dan pemberdayaan masyarakat desa.",
    related: revenueFrom("DD"),
    figure: amountSentence("Dana Desa"),
  },
  ADD: {
    text:
      "ADD (Alokasi Dana Desa) adalah bagian dari dana perimbangan yang diterima kabupaten, " +
      "yang wajib dibagikan ke desa. Banyak desa memakainya untuk penghasilan perangkat desa dan operasional pemerintahan.",
    related: revenueFrom("ADD"),
    figure: amountSentence("ADD"),
  },
  PADES: {
    text:
      "PADes (Pendapatan Asli Desa) adalah pendapatan yang dihasilkan desa sendiri, " +
      "misalnya hasil usaha BUMDes, sewa aset desa, serta swadaya dan gotong royong warga.",
    related: revenueFrom("PADES"),
    figure: amountSentence("Pendapatan Asli Desa"),
  },
  SILPA: {
    text:
      "SiLPA (Sisa Lebih Perhitungan Anggaran) adalah sisa uang dari tahun anggaran sebelumnya " +
      "yang belum terpakai. Di APBDes, SiLPA dicatat sebagai pembiayaan yang masuk.",
    related: (items) => items.filter((item) => item.fundSource === "SILPA"),
    figure: amountSentence("SiLPA"),
  },
  BIDANG: {
    text:
      "Belanja desa dikelompokkan dalam 5 bidang: 1 penyelenggaraan pemerintahan desa, " +
      "2 pelaksanaan pembangunan, 3 pembinaan kemasyarakatan, 4 pemberdayaan masyarakat, " +
      "dan 5 penanggulangan bencana, keadaan darurat, dan mendesak.",
  },
  REALISASI: {
    text:
      "Anggaran adalah jumlah yang direncanakan. Realisasi adalah uang yang sudah benar-benar " +
      "dibelanjakan atau diterima sampai tanggal tertentu. Jadi realisasi kecil belum tentu masalah: " +
      "bisa saja kegiatannya memang dijadwalkan belakangan.",
  },
  BLT_DD: {
    text:
      "BLT Dana Desa adalah bantuan langsung tunai dari Dana Desa untuk keluarga yang memenuhi kriteria. " +
      "Penerimanya ditetapkan lewat musyawarah desa. Nama penerima tidak ditampilkan di TanyaDesa untuk melindungi privasi.",
    related: (items) => items.filter((item) => /\bBLT\b|bantuan langsung tunai/i.test(item.description)),
    figure: amountSentence("BLT Dana Desa"),
  },
  DANA_PER_RT: {
    text:
      "APBDes tidak membagi uang per RT atau per dusun. Anggaran disusun per kegiatan, " +
      "sesuai usulan yang disepakati dalam musyawarah desa. Sebagian kegiatan memang berlokasi di RT tertentu.",
    related: (items) => items.filter((item) => item.entryType === "EXPENDITURE" && item.rt !== null),
    figure: (rows) =>
      rows.length === 0
        ? null
        : `Tahun ini ada ${rows.length} kegiatan yang lokasinya di RT tertentu. Coba tanya, misalnya, "kegiatan di RT 5 apa saja?"`,
  },
  USUL_KEGIATAN: {
    text:
      "Usulan kegiatan desa dibahas dalam musyawarah dusun dan musyawarah desa saat menyusun rencana tahun berikutnya. " +
      "Kamu juga bisa menyampaikannya lewat menu Aspirasi di TanyaDesa, yang diteruskan ke perangkat desa atau BPD.",
  },
};

export function relatedRows(topic: GlossaryTopic, items: ParsedBudgetItem[]): ParsedBudgetItem[] {
  return GLOSSARY[topic].related?.(items) ?? [];
}

export function explain(topic: GlossaryTopic, rows: ParsedBudgetItem[]): string {
  const entry = GLOSSARY[topic];
  const figure = entry.figure?.(rows);
  return figure ? `${entry.text}\n${figure}` : entry.text;
}
